#include <vector>
#include <omp.h>

void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    // Per-thread partial sums of contiguous chunks
    int maxT = 1;
    #pragma omp parallel
    {
        #pragma omp single
        maxT = omp_get_num_threads();
    }
    std::vector<double> threadSums(static_cast<std::size_t>(maxT), 0.0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int T   = omp_get_num_threads();

        const std::size_t chunk = (n + static_cast<std::size_t>(T) - 1) / static_cast<std::size_t>(T);
        const std::size_t begin = static_cast<std::size_t>(tid) * chunk;
        const std::size_t end   = (begin + chunk < n) ? (begin + chunk) : n;

        // 1) Local prefix within each chunk
        double sum = 0.0;
        for (std::size_t i = begin; i < end; ++i) {
            sum += x[i];
            output[i] = sum;
        }

        // Each thread writes only its own slot
        threadSums[static_cast<std::size_t>(tid)] = sum;

        #pragma omp barrier

        // 2) Compute offset = sum of all previous threadSums (serial but cheap: O(T))
        double offset = 0.0;
        for (int t = 0; t < tid; ++t) {
            offset += threadSums[static_cast<std::size_t>(t)];
        }

        // 3) Add offset to this chunk (if any elements)
        if (offset != 0.0) {
            for (std::size_t i = begin; i < end; ++i) {
                output[i] += offset;
            }
        }
    }
}
